```solidity
               uint256 token0BalanceOfVault = _token0.getBalance(address(this)) - msg.value;
	 uint256 token1BalanceOfVault = _token1.getBalance(address(this)); 
	 _charge(_token0, _amount0Max);
	 _charge(_token1, _amount1Max);
```

